) AS (
  VALUES 
    (295::BIGINT, 'Es el PEOR profesor que he tenido, literalmente no le importa enseñar, evalúa materia que nunca explica y es un prepotente que ni preguntas sabe formular correctamente.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-10-05T00:00:00+00:00'::TIMESTAMPTZ, 'cc2fab79dcef01e505ccaee3b2548442cf04250cdc6b8bee66e9814bb04e956a'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, '¡Pésimo profesor! Pierde el tiempo hablando de cosas ajenas al curso. Utiliza un lenguaje muy técnico para querer destacar. Los exámenes son duros y mucho de lo evaluado fue apenas mencionado en clase. No hay un material de apoyo sólido. La calidad de las lecciones y el salario no van de la mano.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2026-01-01T00:00:00+00:00'::TIMESTAMPTZ, '347628836e96308e54b830e092f3bd824974b8a850764a0450cf96f3a1f109cc'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'Los comentarios no son mentira , escribo este mensaje justamente en el momento que el profe se comporta mal , no matriculen con este profe Yo siempre doy una oportunidad a los profes , pero esta vez , si es real'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-31T00:00:00+00:00'::TIMESTAMPTZ, '726733c1cc71825efa28a787a40f9303b3c561f691fa8e94e303d63c5f9f1f15'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'Lo bueno: El profe es buena gente, da buena retroalimentación y no califica duro. Toma en cuenta que: En las clases estarás más perdido que Adán y Eva en Dia de la madre. Se aprende totalmente por uno mismo ensamblador y Linux. DEBES tener un buen equipo, sino el curso va a ser más pesado.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '61eaf2889c411bb66b338c8d75a301ffe4e76776bb53055273616bebbea414f3'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'HUYAN de este mae. La clases son improvisadas, en la cual no hay diapositivas y busca imágenes en Google y las explica en la clase. Y uno de sus proyectos se tiene que hacer de forma presencial. Si no tienes otra opción, debe de tener un buen equipo de trabajo, si no, no pierdas el tiempo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-06-07T00:00:00+00:00'::TIMESTAMPTZ, '5fe98c634a1d5f3ab5445d1490e0b3dbf470babdf897d50e46c43e401cd388c2'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'dios mio un juego en ensamblador'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-05-07T00:00:00+00:00'::TIMESTAMPTZ, 'd7f524d9de1424720189b978c81cf3097298fb104d3a831eead19f4eca76940b'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Da la clase como si ya uno supiera lo que se va a dar y fuera su culpa por no saberlo, para sus evaluaciones, sus clases sirven para muy poco y casi que todo el curso hay que aprender de forma didáctica por que sino pierde el curso, evítelo a toda costa'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-09-12T00:00:00+00:00'::TIMESTAMPTZ, 'b4ed294f670797ea33be2ac17136d19c85401cbdf586c24e4ee57e2b79c213d3'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Cabeza dolor, no explica nada.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'c3395666d813b7b1ebfd9341c6fc7bfc7987191b1bec0434f9630c22bb4d2a1e'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Es un curso pesado en donde tendrás que aprender ensamblador por ti mismo y recordar FOC. Hay bastantes tareas para que al final te "ayude" a hacer los proyectos. Todo lo que se ve en la clase aparece en examen. El profe no explica código durante clases, espero que mejore en eso. Buen profe tho'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f7b458d8eb42bdcd602c6d7c49cebec411aa72dceaa7042dc005bc6566a919c5'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'SAQUENMEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-03-15T00:00:00+00:00'::TIMESTAMPTZ, 'c852abb34f79bf160e771847b9f3aaaf370317c9cc3f77b5262dbc082fa1638f'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'La evaluación del curso está muy repartida en diferentes evaluaciones, el profe da puntos extra al final. Para la programación en ensamblador hay que ser muy autodidacta. A uno le meten mucho miedo con este profe pero no hay que llegar con tanto miedo, es pesado el curso pero el prof es buena gente.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'e264a8c7534a86fa7d7726d7e242b9533543fee85bb85b29d6cd75606bd3b1d9'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-09-28T00:00:00+00:00'::TIMESTAMPTZ, '1469b1814fb01e63616517f71605451d6b53b83f9cd075b990eae1c3095e25c1'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Profesor re-malo. NUNCA matricule con él, acabo de tomar la decisión de dejar el curso tirado porque no esenña nada, mejor me espero al otro cuatri a ver si consigo un profesor decente. Este profesor me recuerda a Kirstein, deberían despedirlo porque como profesor no sirve'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-08-10T00:00:00+00:00'::TIMESTAMPTZ, '1306a3d6a4078cdc0f200af36897d06f77f83161d7319b464537433ae8d4de0a'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'Buena persona, terrible profesor. Las explicaciones son confusas, parece que se molesta cuando uno pregunta algo, deja una cantidad excesiva de tareas, los proyectos son increíblemente largos y los exámenes los hace A PAPEL! Cuiden su salud mental y no matriculen con él'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a251990d9c08dbb272298888a24815344491cd581b2df7a3a980df95caa58c78'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Tiene la mejor calva de todo el TEC'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0dcb44b7c150b9b185e67c0ee575150e3409094193ea0bf6c2bcf970c042d031'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Siempre llega tarde y tras de eso gasta 40 minutos criticando al gobierno o hablando de temas que a nadie le importan y cuando por fin se digna a dar la clase todo el material es súper denso, de esos profes que les gusta jugar de intrépidos hablando puro lenguaje técnico para dejarlo a uno perdido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-09-18T00:00:00+00:00'::TIMESTAMPTZ, '0281a75cf4c0fde81c91e6250aae686e5e4d3a734108e1671041f72144d6e734'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'Todo el semestre llegó tarde, todo lo complicaba de más y se la pasaba jugando de perfeccionista en las revisiones solo para joderlo a uno, lástima que no jugó de perfeccionista para dar clases ya que fue una completa porquería cómo profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-03T00:00:00+00:00'::TIMESTAMPTZ, '7cd41b4ad1a56d47601d20b2f864a741c2389a82c93c831e0db7c4729b255201'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'Alguien digale a este señor que está dando clases y que no es un centro de charlas sobre la vida de él. Llega a contar su vida, luego deja una tarea de algo que nunca explicó y después se pone en plan "esto es el TEC chicos tienen que ponerle" para tapar el hecho de que es una m... de profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd4e0ad9a5b56c761d1ca99c00d72645f850ec44480beedfeeb0ada9495e9e594'::TEXT, ARRAY[1020, 1117]::BIGINT[]),
    (295::BIGINT, 'Es de lo peor que me he topado en mi vida, le encanta complicar las cosas y dejar trabajos con cosas que no se han visto en clase para ver sufrir a todos'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-05-17T00:00:00+00:00'::TIMESTAMPTZ, '3375bcaca0b8584fdc2c279c1616d53c3432b3e192f31d5dcc89ebf7dd32f51f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Este profesor llega tarde a TODAS las clases (incluso las virtuales). Se pone a hablar de cosas que ni siquiera son de la materia. No ayuda, no brinda explicaciones claras, tiene una actitud pedante. NO MATRICULEN CON ESTE PROFE PORQUE NO VAN A ENTERNDER NADA DE LO QUE LLEVAN'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-05-17T00:00:00+00:00'::TIMESTAMPTZ, '5be64c48cebae19757d15e46aea75968143514a3ede416c8475fac60c698dbb7'::TEXT, ARRAY[1163]::BIGINT[]),
    (295::BIGINT, 'Todo lo complica, no busca ayudar al estudiante al contrario busca que uno "se esfuerce de más" (se esclavice) a su materia porque cómo esto es el TEC en el TEC no se duerme... tristeza es lo que dan estos profesores que son un atentado a la salud mental de cualquiera'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-26T00:00:00+00:00'::TIMESTAMPTZ, 'b76695653fe7b0aba9a561c70c5d303325c2949d2bd26ae1bfbabeb3963889e3'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (295::BIGINT, 'De lo peorcito del semestre, el mae es feliz complicando todo sólo para jugar de duro'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'fc4e72421aef2911e4d3545390d3222938ff921ca1a57d9a1fd36d4879469f34'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Es demasiado necio con lo duro que es el tec, en las clases solo lee las diapositivas y no da ejemplos antes de dejar 100 prácticas, tareas y exámenes. Espera que todo el mundo sepa de todo y puedan hacer cualquier tipo de ejercicios sin haberlos visto nunca.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-03-18T00:00:00+00:00'::TIMESTAMPTZ, '430b8242ee738c761e79a17b747eb013779190a54b9bbbcdbda329225c29f66c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Tiene una metodología muy extraña pues no enseña ensamblador y hay que terminar aprendiendo solo. Da mucha ayuda si uno pregunta y es un curso pasable si se entregan los trabajos estén completos o no.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '9e6b89f956d6c2452f6c8939d4288394382dfeeb78eaaa9bc90864b446dfd0ca'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Juega de ortodoxo y del gran ingeniero cuando en realidad sólo es un profesor más que le encanta complicarlo todo con tal de monstrarle al alumno que "esto es el TEC y aquí hasta respirar es difícil"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'ab005d7c75e5b6296c083ffbcce8af4cc0b24579850ccbc5747b64b9a1f63c1a'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Buena persona, mal profesor, deja a los estudiantes a su suerte con ensamblador, todo hay que aprenderlo de YouTube, deja muchas tareas y proyectos engorrosos,a la hora de pedirle ayuda probablemente lo enrede más de lo que está, procure encontrar un buen grupo de trabajo o le aseguro que va a mamar'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-11-19T00:00:00+00:00'::TIMESTAMPTZ, '3a7c4dae762cd5fb304d401a4c52042d4bc7321a448deb4a8961bb0ffd71d011'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Este señor es la definición de "un título no define tu inteligencia", mucho titulito TEC, muy creído de que por ser del TEC es un crack pero la realidad es que sólo es un pésimo profesor que no sabe dar clases y uno prácticamente se enseña solo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-11T00:00:00+00:00'::TIMESTAMPTZ, '112304d6010c0a7be6a756cf78449c04ba08810d5934d04d2b59212ec4a233d5'::TEXT, ARRAY[1020, 1117]::BIGINT[]),
    (295::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-11T00:00:00+00:00'::TIMESTAMPTZ, '75183b1f260bdc5e2ac6a58db79a6727f73c531f5d1ae87894c7aa6f341f288c'::TEXT, ARRAY[1020]::BIGINT[]),
    (295::BIGINT, 'Un mae que quiere jugar de "super ingeniero" cuando claramente está detrás del palo. Tiene esa idea de que los estudiantes somos máquinas de trabajo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-09T00:00:00+00:00'::TIMESTAMPTZ, '9affe06e482e0b3bfbb59710fbe2a057323260e93976db97f3cd51bfd117a025'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Una embarcada total, el mae no enseña absolutamente nada útil, ud aprende ensamblador en Youtube. Insoportable con las documentaciones, deja tarea desde la primera semana, lo que no explica lo pide de trabajo de investigación.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-27T00:00:00+00:00'::TIMESTAMPTZ, '9bc6bae4bd66dcfa17b3b3b929d621591895ed8a488edcbd499cb8e7245187dd'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Este viejo solo sabe joder mae JODER, juega de perfeccionista y en realidad es un gran cabrón que no sirve para ni picha, no ayuda, solo deja trabajos engorrosos y con el cuento de "esto es el TEC" quiere que uno se trague un pichazo de tareas, ojalá no tenga el disgusto de volvermelo a topar'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'a446c583685c2a9a8c2df61524b68f93f24124a65ddec60a774707dd588cd9be'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Hay que ser 100% autodidacta, él no te va a enseñar ni un "hola mundo" en ensamblador pero eso sí, pide proyectos cómo si enseñara un montón. Las clases son una pérdida de tiempo. Evitelo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '89a4aeac8907ef51535b59a84633ef4a6e41ea69c4907be8f0ce882137357c33'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'No es bueno , ni tampoco malo, es profesor que deja demasidas tareas que por lo general no explica bien (ensamblador), si puede evitelo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7445f006ccec14b9046b2609d407d5d9c9ff3b6778a9a36f7a1afbac7b863261'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Como persona es muy pura vida, sabe bastante pero no sabe transmitirlo al estudiante, deja muchos trabajos, no enseña casi nada respecto a programar a ensamblador, llega tarde y no graba. Uno tiene que ser autodidacta y dedicarle mucho a programar. En consulta sí se enfoca en ayudar, es lo bueno.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '100c754061ac42fc8730da4a1423c9754f9a82bc11d287fbc1962c2ae0d7aa63'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'El mae es una mierda, tratar de hablar con él es para que a todo le tenga una "respuesta" robotizada (tenía que ser del TEC...). Demasiado cuadrado además de que espera que uno haga absolutamente todo mientras él se gana el salario a base de "leer presentaciones". Que rico que a un le paguen por eso'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5bc7ea805011258a7cb237e821b516896ebd8fa388a5b4594441599a135166c3'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'La verdad no es tan malo como dicen, si se habla claro con él, comprende y trata de ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b958b015f28532402d4aa9b6257fe089c8d6aff4f451de8c3069212012e956d4'::TEXT, ARRAY[1117]::BIGINT[]),
    (295::BIGINT, 'Un asco de profe, clases largas, no enseña nada, todo lo complica de más, en las revisiones es super minucioso con todo y a todo el encuentra un "pero". Pedirle ayuda es perder el tiempo, lo enreda más. Un profesor que le encanta la idea de "sello TEC" para ponerlo a uno a parir innecesariamente'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b9f44698ae7ebcaa959f0a05f53cca2aeb85b7dbe74631c0de0c93baccf86ed1'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Para hablar de Canessa se ocupan muchas páginas. Es un profesor con mucho conocimiento, pero le falta aprender como transmitirlo. Las clases son pesadas, pero en hora de consulta, si usted tiene claras cuales son sus dudas, él lo va a ayudar sin problemas. No enseña ensamblador, uno aprende solo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Da crédito extra']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c82842ff7f99ef91dfd7b254ba347d379a6eb8033229cded4f9a2e1ee2ca073b'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'En las evaluaciones de proyectos se saca aspectos para quitarle nota a uno de la nada, deja muchas tareas grupales y largas, las clases son aburridas y espera que uno sepa todo. Como persona es buena, pero como profesor es mediocre.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c396a1cef0b62ecf7f26d847d2ae5b002597ed3d64a40fcdcc330ec761b65830'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Es un IMBÉCIL, es un completo idiota, no debería ser profesor. Talvez el sepa mucho sobre la materia pero no sabe explicarla, es un idiota, no me importaría que muera el día de mañana en lo absoluto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'fa628298e039edcc611d190e1a5721ed00b30515d99c1be7f29b0e42bf715bd8'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Nada de ayuda al estudiantes, pasamos de un curso de 18 a estar 7 de los cuales solo van a pasar 2 que son repitentes de los dos semestres anteriores. Fue una completa desgracia para mí al punto de abandonar ambos cursos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'fca641442ba743ef8ff22068392c0ad85cee86e756dc806a0110b755de931260'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Yo no pagué 80 rojos de matrícula para una clase donde un mae se la pasa hablando de su vida privada y solo sabe dejar "investigaciones" porque resulta que las clases son más un conversatorio que otra cosa. Para lo único que es bueno es para dejar tareas y proyectos cargados de complicaciones'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'fc59f44524e4ff29c729cdc84864cddbe0cc081b7575c11d497c68c6cfe80099'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Un profesor que para lo único que sirve es para que ud pierda el tiempo. Las clases son inútiles, el profesor no ayuda, ir a consulta es para que lo enrede más. El curso sería más fácil sin profesor y con un temario, total este mae de leerte la diapositiva y hablar de su vida no pasa...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-05-31T00:00:00+00:00'::TIMESTAMPTZ, '44174005debd0356d48132d5850fec076b3916adf7fba6376db7136909340124'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'No va aprender nada de ensamblador o algo que tenga que ver con Arquitectura, es usted quien se ayuda solo, el señor se pierde en la clase, las presentaciones que tiene no sirven PARA NADA!!, yo pase el curso viendo puros videos de un Hindú que si sabia de ensamblador. META CON OTRO PROFESOR!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-05-21T00:00:00+00:00'::TIMESTAMPTZ, '2ae6517af74f8a57209d1070420715c08d344738cd615d25e7db72cc1851e359'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Llega tarde como mínimo 15 minutos por clase hasta en virtualidad. Conoce mucho del área que enseña, probablemente sea un buen ingeniero. Cómo profesor las clases suelen ser muy cargadas y pretende que la mayor parte del aprendizaje sea por cuenta propia. Si quiere pasar asista a consulta.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '73bdadd01a4d0fde7e537c7257e699405f047368d340ca5abf7983a7be2bbeed'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Todo lo que no se ve en clases por estar llegando tarde o estar contando su vida lo envía de tarea. En pocas palabras, ud no tiene profesor, se enseña solo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'c67a8d40410ee6ff3eba7331c177e57e6d6a4c18d19ea62b64e20f4bc6caa31b'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'PAYASO! En lo que llevamos del semestre sólo pasa hablando de su vida, llega tardísimo y termina las lecciones tarde, para todo deja tarea (claro, cómo no explica, entonces a uno le toca educarse solo) y si uno se queja entonces se echa una hablada de que "para él también es difícil"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-10-25T00:00:00+00:00'::TIMESTAMPTZ, '82507373199afc041c438219731c38348e461a2f598a6cbe35a664014e51ac12'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Todo el semestre usted va a andar buscando un profesor que no va a encontrar, el mae manda de tarea lo que le da la gana y de excusa pone que tienen que investigar, pone limites de tiempo como si explicara todo y no se da cuenta de que nadie entiende nada de la materia. Un Imbécil.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'e94c1d4de3b75f4316678c00a7d5304e6952b1532615250d6603c520371b9ddb'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Este mae es increíblemente negligente con su trabajo y no representa la calidad del TEC. Desperdicia como 45 mins de clase en temas no relacionados con la materia y lo pone a uno después a leer libros de 500 paginas y presentaciones con texto pegado sin explicación. Nunca llega a tiempo a la clase.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2020-10-16T00:00:00+00:00'::TIMESTAMPTZ, '0b8865b5c1d6a67f3b15a0ec6861c52b969bbeaf81e10393b126d2144763b8cb'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Usa las clases para dar "charlas motivacionales" que nadie le pidió, ojala usara ese tiempo para ser mejor profesor y no estar dejando mil tareas para llenar el hecho de que ni nos explica la materia.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-10-16T00:00:00+00:00'::TIMESTAMPTZ, '6e774eebc0f46a5da89846e9a09a42a965f1899d16758402505c6a3bebfc9da2'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Las clases se van entre hablar de su vida privada y dejar "tareas" que en realidad son la clase. En pocas palabras, ud va, lo escucha hablar de su vida, sale de la clase y se pone a estudiar arqui. Además preguntarle algo es perder el tiempo, no sabe dar una explicación clara.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2020-09-16T00:00:00+00:00'::TIMESTAMPTZ, 'a1bd511ee86ea84d26bf3009eb5589208115270a0f06cd902d5646301ebd9aba'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'En lo que va del semestre, el profe no ha hablado de básicamente nada importante del curso, se pasa las clases hablando de su vida privado u otras cosas no relevantes. Además de que quiere que uno investigue todo lo que necesita para las tareas y se se le pregunta algo no tiene disposición de ayudar'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-09-12T00:00:00+00:00'::TIMESTAMPTZ, '2f0587e8ae24e964c9b19cdc1886d9c641359a9803de74acd3379bbb1af601ed'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Incompetente, nada de lo que hace en clase es importante, y la materia que deberíamos aprender la manda como tarea a aprenderlo por nuestra cuenta. Las clases son 3 horas de escucharlo a hablar de cosas innecesarias, y las cosas que si explica las explica mal. Matricular con él es un error.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-09-09T00:00:00+00:00'::TIMESTAMPTZ, '0f660e0f3bfbaa17781059cbd00367e859fdc0a639291b3565508dbf2455d5d3'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Llevo 3 clases y este mae no para de hablar de su vida personal. Es una COMPLETA BASURA, no es broma. Es probablemente el peor profesor de toda la Sede de San José. Por amor a Dios no matriculen con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2020-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'ff8989fb967ab0477017f7263eab8900ebc0897acf14282018998ce634a370dc'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Lo que dijo el de abajo, chichipato x2'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '2cee43b5561ddf9794523fcb5f14b4afc84f22ae55e57bfdd65bdc69f2b5b576'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Mucha materia, poco pelo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '8e73932898a6aa1b44487c3c6fe5fdebc0e5c40dfcf9ba1778a1c1057aadb2f8'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Siempre llega tarde y tras de eso habla de su vida media hora. Solo lee las presentaciones, y de vez en cuando explica el código. Deja bastantes tareas en intro y en taller los proyectos son realizables. No fue ni bueno ni malo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '4f4f286ade7c02d55046e1c3bbe28f31cb9ba6f14449cb963b1b12de612dae55'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Chichipato.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '7a7bb5377f02a0a271c22b572cfcbef27ee321223010177ed88ab5fb65db6e2e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, '9 tareas "cortas" + 8 quices + 2 tareas programadas + un proyecto que se divide en 3 partes + 2 exámenes = 24 asignaciones por parte de este profesor en tan sólo 17 semanas. Además hay que ir a classes obligatoriamente aunque se vaya a perder media clase hablando de situaciones ajenas al curso.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '295d323753dac9fda5549c10fb90926e1de091e386c6964cb2cfaece21cc1b23'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Semana 16 y este señor sigue dejando tareas grupales a la par del proyecto final y para variar pretende que todos participemos activamente en una clase que dura 2hrs y media o si no, time un quiz... Yo me imagino que él piensa que su clase vale unos 8 créditos. Evitenlo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'a37435be2d47df33e8a0ec1bf9902c69dd7f3b595d069754dd473df75595e155'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Es buena persona y trata de "ayudarte", pero tiende a complicar la materia innecesariamente, si está con él tienes que ser MUY autodidacta por que no espere aprender mucho de las clases, deja trabajos de cosas que no explica y llega casi siempre tarde a las clases por ende terminan muy tarde.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'fcf4272d102bb1dcb8c002700a6e92954ccc25ef32ff626fc021ecce1447b088'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Es muy buena persona, pero (y es un gran pero), no enseña nada en clase, practicamente tienes que enseñarte tu solo. No se le entiende bien, ya que se complica mucho sus explicaciones cuando hay maneras más simples de realizar las cosas. Deja trabajos muy complidados. Si pueden, no lleven con él.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'd1d29ee7b1f5393bb399e01a71c5e293f1fbafcc28ff1be55523eb9e7a8249c7'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Un compañero y yo siempre que saliamos de clase deciamos lo mismo, Canessa debería ser profesor de comunicación oral, escrita, seminario, ambiente,etc. Ya que es buena gente, pero para una materia de ingeniería es pésimo, no sabe explicar y es muy duro. El profe creo que se equivoco de carrera.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-07-15T00:00:00+00:00'::TIMESTAMPTZ, '5d0bfbf6aa900146a308ddb87c6e374e4fcb9414c2e7f77876169c400990724b'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Llegó todo el semestre tarde, siempre había quiz, extendía las clases hasta las 11:50 o 12 (iniciaban 9:30), dejaba trabajos super largos de materia que ni explica porque a clases se va a hablar de política o de sus experiencias cuando era estudiante. Si ud ya ha llevado el curso dele, si no,evitelo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-07-14T00:00:00+00:00'::TIMESTAMPTZ, '2ee0ce031af723ca408cc13625d9f305c66540597abf6f3b0b6fbc83f57920f4'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Ya las progras por sí solas son complicadas y más cuando el profesor te dice que no puedes usar bibliotecas, a eso súmele que siempre pide una documentación larguísima y detallada de todo y por más tuanis que Ud trate de hacerla, siempre con algo se le va a quedar mal. Evitelo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-06-07T00:00:00+00:00'::TIMESTAMPTZ, '3589655b938eedce3bce8ed2429a724acc81336781dc068e7fe61c390b82f68a'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Este profesor sabe cómo convertir todo en complicado, desde la progra hasta la documentación. Se le olvida que su materia no es la única.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-05-30T00:00:00+00:00'::TIMESTAMPTZ, '18ef1857fa474333badc23545b18504a37598626b091af6c5b90fddf32bcffe3'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Demasiado irracional con las tareas y trabajos, piensa que uno es una máquina. Desde el primer día dice que todos los días hay quiz excepto cuando él diga que no hay. La asistencia es obligatoria sin embargo en clase no se hace nada aparte de leer diapositivas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-05-28T00:00:00+00:00'::TIMESTAMPTZ, '157e280bc27202e03b81c5895bf413403da951d7e37a31de3485ecf66944df14'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'Es increíble la cantidad de ***** que pide el profesor para un sólo trabajo, y toda documentación tiene que ser en Latex porque a él no le gusta Microsoft, parece que le encanta hacerle la vida imposible a los estudiantes haciendo los trabajos mucho más complicados de lo que son.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2020-05-27T00:00:00+00:00'::TIMESTAMPTZ, '5047938ed2b914d7a56dcd67e5d1b215e85abc911381f9b58dfd9ed41bfb3aa3'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'Al profesor le encanta ponerse en "modo creativo" y dejar trabajos sumamente enredados para que "ud aprenda" cosa que al final se traduce cómo "deje morir otra materia para que se concentre sólo en la mía innecesariamente".'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-05-26T00:00:00+00:00'::TIMESTAMPTZ, '28ee92a1c00ea8600d1b700ff407297c5a7e45ccfa17e420abf0b132af0b9b61'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'El profesor no sabe compartir su conocimiento, él piensa que hablar super técnico es dar clases. Al aula se va a conversar de cosas que ni suman y cuando se tiene una duda el profesor no haya cómo ayudar, solo te repite cómo es el procedimiento, a todo eso súmele cada semana hay Quiz y tarea.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'aee612bc5bd54c5b77a1e1c40efeddddd08bbf36b0e8f09e34b8499c0ee58d2f'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Demasiado técnico, el profesor se le olvida que está hablando con estudiantes y no con otros ingenieros. Sus explicaciones son super teóricas y complejas, Ud termina más confundido. Si usted es muy autodidacta y lleva menos de 2 materias, dele, de lo contrario prepárese para parir.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-05-20T00:00:00+00:00'::TIMESTAMPTZ, '2c438cb2d98f24a01412092d9085778cdf78ec6a8da35ae68cc7b5b92ae2f99a'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'Siempre llegaba tarde y la mitad de sus clases se basan en conversaciones de su vida. Sus clases son super teóricas, rara vez usted ve o entiende cómo se puede aplicar algo a la vida real.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-05-19T00:00:00+00:00'::TIMESTAMPTZ, '592b13ac820bb00a2ec11e6729e940c458b136982a858da3ce933a82d5caca5a'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Si lo que quiere es aprender, evitelo, al final es más el desgaste que lo que aprende, el profe no entiende que su materia no es la única.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'a9e7cc1bba7fc792c2b1877e911d5bd852d219a3ded81c42d08e079376632d18'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Llevar con este profe es cómo agarrar un libro de física avanzada y tratar de leerlo sin conocimiento previo: mucho lenguaje técnico, mucha teoría y a la hora de la práctica ud termina vuelto loco en google tratando de entender la materia. A eso súmele que todas las semanas quiz + tareas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-05-12T00:00:00+00:00'::TIMESTAMPTZ, '5d9939eefa69f5a3ada8a27718011446dcb81ce091fcd9bbd0e94783d5fdd86c'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Cómo persona es excelente, cómo profesor es pésimo, de nada sirve un profe que te da más tiempo para un trabajo o te deje usar un "forro" en el examen si sólo llega a leer pdfs y deja trabajos super pesados de materia que ni explica y todo se basa en "investigue".'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muy cómico']::TEXT[], '2020-05-12T00:00:00+00:00'::TIMESTAMPTZ, '4b12d2b421ad4ed7014b3721fa3ca373f8c48180dcbd1411be97bc36c8405075'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'Buena persona, mal profesor, deja tareas de temas que ni siquiera ha iniciado a explicar y debe entregarlas en tiempo menos a una semana, asume que ud sabe las cosas... Clases obligatorias a pesar de que a veces solo se va a vacilar'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-21T00:00:00+00:00'::TIMESTAMPTZ, '57ccbbb763d41dc4833f11d10d94bb43f7ff5a27bdc8de2f0b33a4cbe0c2d8c2'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'Deja usar material de apoyo y escuchar música en los exámenes, suele asumir que uno tiene algo de conocimiento previo y normalmente prefiere que uno pruebe e investigue en lugar de explicar él'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a8626beaf84ebcd6aaca7a74674382ff00fa7e0af5c69cc0773975cb5fcc92cd'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'fc20b91ad389889603fdab95c6e341a5f411d639d9bdf9dd959895e9e86d56c2'::TEXT, ARRAY[1032]::BIGINT[]),
    (295::BIGINT, 'El profe es bastante bueno, siempre está en horas de consulta, y si hace las prácticas para el examen va sobrado. Sin embargo, sí son demasiadas tareas bastante largas que requieren demasiado tiempo extraclase y que uno sea autodidacta. Tiene que tener todas las tardes libres para lograr hacer todo.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '337f1e87fec0b5a078001d7a016d1c0957f65e997271969dfc88221e10907986'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Es una excelente opción! el profe deja muchas prácticas eso sí, pero si usted las hace pasa el curso sobrado, al igual siempre esta disponible para consultas y para ayudarlo a uno.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-14T00:00:00+00:00'::TIMESTAMPTZ, '42d713669f5a1afef0b8450054bb1ab088708393038656ad7af7a3e8cffff187'::TEXT, ARRAY[3022]::BIGINT[]),
    (295::BIGINT, 'Excelente profesor! Recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, '662e13e71fd24f3aa6f86a11c7055e5b68fda7b6e86d8f37949a8b01ee5b6d36'::TEXT, ARRAY[1017]::BIGINT[]),
    (295::BIGINT, 'No tiene idea de la relación creditos-trabajos extra clase. Es increible que un laboratorio sea el curso que más tiempo quita en el semestre. Pide demasiada basura en los informes y bitacoras. Pesimo no volveria a llevar un curso con él. Ni sabe nada de la teoria'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, '9a06ce00326a082b214d1e6765745e254abee77f877e56f9077f1b8190753a2a'::TEXT, ARRAY[2968, 1261]::BIGINT[]),
    (295::BIGINT, 'No se aprende mucho que digamos con el! El curso es DEMASIADO pesado con el, tanto así que ni uno de 4 creditos quita tanto tiempo. Trata de cubrir demasiados detalles como la ortografía, y si se le pide ayuda en el laboratorio solo toca todos los botones.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b8d6ebbc62de8a485d4f7eae7326e0fa89427de94ebf623e71f797c056520b9d'::TEXT, ARRAY[3050]::BIGINT[]),
    (295::BIGINT, 'La clase es muy fácil pero no se aprende nada. Si lo que quieren es aprender NO lo recomiendo!!!'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2016-07-12T00:00:00+00:00'::TIMESTAMPTZ, '6f12eaba0faf55e1ab4cd2e05bf45573f7327c1e6ecffca9d707508202665d7d'::TEXT, ARRAY[1063]::BIGINT[]),
    (295::BIGINT, 'Excelente profesor, se aprende mucho, domina bien el tema y califica normal'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '13bb94e174cce39d1acc4eec86fc8a7896c693eecd38d279fc61409e7f0a1e28'::TEXT, ARRAY[3050]::BIGINT[]),
    (295::BIGINT, 'El profe ayuda bastante, es muy pura vida y conoce del tema'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '975c3e60b2f7582336a9ba367bf39c92ef81713e709dc31be06f8fc6c3e16e34'::TEXT, ARRAY[2968, 1261]::BIGINT[]),
    (295::BIGINT, 'Es muy buen profesor, explica bien y es una excelente persona. Se preocupa y ayuda si se tiene una situación personal, deja mucha practica no obligatoria por la que da puntos extra. También da puntos extra en los proyectos y exámenes.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2016-04-17T00:00:00+00:00'::TIMESTAMPTZ, 'b289850449678999d5580a21f705021289e979efd2ab678ac2fb6b90bc4e66c2'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Da un ambiente amistoso, pero es demasiado cerrado en cuanto a flexibilidad, si se matricula con el, independiente debe ser (mucho).'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '10ff28a2a77fe17f6aca0c31ae996e6779b0fb2741de5a9796c697fda21f182b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Excelente profesor'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-05T00:00:00+00:00'::TIMESTAMPTZ, '0ee271e586cb0370091d505b42e43c938a5347f42a73d181c93e245dbd65b166'::TEXT, ARRAY[1020]::BIGINT[]),
    (295::BIGINT, 'NO es fácil con él, pero se aprende mucho y se preocupa por los estudiantes, totalmente recomendado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'cd71956227ca15c65fb6b60087d1694879004e0ba2a053e7321e1032da980593'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'paciente y respetuoso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'bdcb9e72d124580031cbafea886dad66cd51ef6d1da372c654236b5ad9fc951e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (295::BIGINT, 'Explica demasiado bien y deja bastantes trabajos y practicas las cuales le ayudan en el conocimiento y así uno va preparado para los exámenes'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '9b487d9a6cbcd9ece8253bf43c027a11de98eb313b08d5b61ae656f10084be66'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
